package com.dat.ai_receptionist_web.service.Catalog;
import com.dat.ai_receptionist_web.domain.Catalog.*; import com.dat.ai_receptionist_web.dto.*; import com.dat.ai_receptionist_web.dto.Catalog.*; import com.dat.ai_receptionist_web.enums.Catalog.AddonStatus; import com.dat.ai_receptionist_web.error.*; import com.dat.ai_receptionist_web.error.code.CatalogErrorCode; import com.dat.ai_receptionist_web.mapper.Catalog.TrainingPlanAddonMapper; import com.dat.ai_receptionist_web.repository.Catalog.*; import com.dat.ai_receptionist_web.repository.Finance.EnrollmentAddonPurchaseRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class TrainingPlanAddonService {
 private final TrainingPlanAddonRepository repository; private final TrainingPlanService plans; private final EnrollmentAddonPurchaseRepository purchases; private final TrainingPlanAddonMapper mapper;
 @Transactional(readOnly=true) public PageResponse<TrainingPlanAddonDTO.SimpleResponse> list(UUID planId,AddonStatus status,Pageable pageable){return PageResponse.of(repository.findAllDetailed(planId,status,pageable),mapper::toSimpleResponse);} @Transactional(readOnly=true) public TrainingPlanAddonDTO.Response get(UUID id){return mapper.toResponse(find(id));}
 @Transactional public TrainingPlanAddonDTO.Response create(TrainingPlanAddonDTO.CreateRequest r){var e=new TrainingPlanAddon();e.setTrainingPlan(plans.find(r.trainingPlanId()));mapper.updateEntity(r,e);return mapper.toResponse(repository.save(e));}
 @Transactional public TrainingPlanAddonDTO.Response update(UUID id,TrainingPlanAddonDTO.UpdateRequest r){var e=find(id);if(purchases.existsByAddon_TrainingPlanAddonId(id)&&(e.getExtraSessionsPerWeek()!=r.extraSessionsPerWeek()||e.getPrice().compareTo(r.price())!=0))throw new ApiException(CatalogErrorCode.TRAINING_PLAN_CONFIGURATION_LOCKED);mapper.updateEntity(r,e);return mapper.toResponse(e);} @Transactional public void delete(UUID id){if(purchases.existsByAddon_TrainingPlanAddonId(id))throw new ApiException(CatalogErrorCode.TRAINING_PLAN_IN_USE);repository.delete(find(id));}
 private TrainingPlanAddon find(UUID id){return repository.findDetailedById(id).orElseThrow(()->new ApiException(CatalogErrorCode.TRAINING_PLAN_ADDON_NOT_FOUND));}
}
